---
/**
 * Renders the `map-move` result style: a per-answer map (work getting more
 * valuable vs. work a tool can take) plus one recommended move. Everything the
 * component prints comes from the quiz's `mapMove` frontmatter and the chosen
 * options' sentences, so the engine stays free of any site-specific wording.
 *
 * The design is a map, not a grade. There is no number, letter or tier title
 * anywhere on the page: the lead visual is `MapMoveShape`, whose boxes are
 * sized by the proportion of time that went to each kind of work, and colour is
 * always backed by an icon, a label and a position so it survives greyscale and
 * colour-blindness. Surfaces are flat with hairline borders; the one move is
 * the single block allowed a heavier border, because it is the payoff.
 *
 * The page passes the taker's decoded responses; scoring/selection happens in
 * `computeMapMove`. This component is presentation only.
 */
import { computeMapMove } from '../map-move';
import type { MapMoveEntry, QuizData, QuizResponses } from '../types';
import MapMoveShape from './MapMoveShape.astro';
import QuizIcon from './QuizIcon';

interface Props {
  quiz: QuizData;
  responses: QuizResponses;
}

const { quiz, responses } = Astro.props;
const mm = quiz.mapMove;
const result = computeMapMove(quiz, responses);

// Minimal, escaped inline markdown: `[label](url)` links only. Content is
// author-controlled (frontmatter), but escaping first keeps this safe if that
// ever changes.
function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function renderInline(text: string): string {
  return escapeHtml(text).replace(
    /\[([^\]]+)\]\(([^)\s]+)\)/g,
    (_m, label: string, url: string) => {
      const external = /^https?:\/\//i.test(url);
      const attrs = external
        ? ` target="_blank" rel="noopener noreferrer"`
        : '';
      return `<a href="${url}"${attrs} class="text-quiz-accent-strong underline">${label}</a>`;
    }
  );
}

function paragraphs(text?: string): string[] {
  if (!text) return [];
  return text
    .split(/\n\s*\n/)
    .map((p) => p.trim())
    .filter(Boolean);
}

// Each answer's icon comes from the option the taker chose, so the map reads as
// concepts rather than bullets.
function iconFor(entry: MapMoveEntry): string | undefined {
  const question = quiz.questions.find((q) => q.id === entry.questionId);
  return question?.options[entry.optionIndex]?.icon;
}

const heading = mm?.heading ?? quiz.title;

// A context answer with no `mapSentence` has nothing to say. Filtering here
// rather than in the loop also keeps the panel itself from rendering as a bare
// heading over an empty list.
const contextWithSentences = result.context.filter((entry) => entry.sentence);

/**
 * What the payoff block should say. `'none'` drops the block entirely rather
 * than printing an accent-bordered box containing only its heading, which is
 * what a taker who answered in the middle of every question used to get: no
 * move to make, but not well positioned either, so neither branch had copy.
 */
const moveBody: 'wellPositioned' | 'move' | 'noMove' | 'none' =
  result.wellPositioned && mm?.wellPositioned
    ? 'wellPositioned'
    : result.reclaim?.sentence || result.redirect?.sentence
      ? 'move'
      : mm?.noMove
        ? 'noMove'
        : 'none';
---

<div class="mx-auto max-w-170">
  <header class="mb-8">
    {
      mm?.eyebrow ? (
        <p class="text-quiz-accent-strong mb-2 text-sm">{mm.eyebrow}</p>
      ) : null
    }
    <h1 class="text-quiz-ink text-2xl/tight font-bold md:text-3xl/tight">
      {heading}
    </h1>
    {
      paragraphs(mm?.opening).map((p) => (
        <p
          class="text-quiz-ink-secondary mt-4 text-base/relaxed"
          set:html={renderInline(p)}
        />
      ))
    }
  </header>

  {/* The lead visual: proportions, deliberately without a number on them. */}
  {
    mm?.shape && result.shape ? (
      <MapMoveShape
        config={mm.shape}
        shape={result.shape}
        fromBoxId={result.reclaim?.sentence ? result.reclaim.boxId : undefined}
        toBoxId={result.redirect?.sentence ? result.redirect.boxId : undefined}
      />
    ) : null
  }

  {/* The map: two columns, what is gaining and what a tool can take. */}
  <section class="mb-8 grid grid-cols-1 gap-3.5 md:grid-cols-2">
    <div
      class="border-quiz-hairline bg-quiz-card rounded-xl border-[0.5px] p-4 md:px-5"
    >
      <h2
        class="text-quiz-valuable-strong mb-3 flex items-center gap-2 text-lg font-bold"
      >
        <QuizIcon name="gaining" size={18} />
        {mm?.gainingHeading}
      </h2>
      {
        result.gaining.length > 0 ? (
          <ul class="space-y-3">
            {result.gaining.map((entry) => (
              <li class="flex items-start gap-2.5">
                <span class="text-quiz-valuable-strong mt-0.5 shrink-0">
                  <QuizIcon name={iconFor(entry) ?? ''} size={18} />
                </span>
                <span
                  class="text-quiz-ink text-base/relaxed"
                  set:html={renderInline(entry.sentence ?? '')}
                />
              </li>
            ))}
          </ul>
        ) : mm?.gainingEmpty ? (
          <p class="text-quiz-ink-muted text-base/relaxed">{mm.gainingEmpty}</p>
        ) : null
      }
    </div>

    <div
      class="border-quiz-hairline bg-quiz-card rounded-xl border-[0.5px] p-4 md:px-5"
    >
      <h2
        class="text-quiz-slipping-strong mb-3 flex items-center gap-2 text-lg font-bold"
      >
        <QuizIcon name="slipping" size={18} />
        {mm?.slippingHeading}
      </h2>
      {
        result.slipping.length > 0 ? (
          <ul class="space-y-3">
            {result.slipping.map((entry) => (
              <li class="flex items-start gap-2.5">
                <span class="text-quiz-slipping-strong mt-0.5 shrink-0">
                  <QuizIcon name={iconFor(entry) ?? ''} size={18} />
                </span>
                <span
                  class="text-quiz-ink text-base/relaxed"
                  set:html={renderInline(entry.sentence ?? '')}
                />
              </li>
            ))}
          </ul>
        ) : mm?.slippingEmpty ? (
          <p class="text-quiz-ink-muted text-base/relaxed">
            {mm.slippingEmpty}
          </p>
        ) : null
      }
    </div>
  </section>

  {/* Context: the constraints. Visibly softer, and never counted as a gap. */}
  {
    contextWithSentences.length > 0 ? (
      <section class="bg-quiz-context-panel mb-8 rounded-xl p-4 md:p-5">
        {mm?.contextHeading ? (
          <p class="text-quiz-ink-secondary mb-3 text-sm">
            {mm.contextHeading}
          </p>
        ) : null}
        <ul class="space-y-3">
          {contextWithSentences.map((entry) => (
            <li class="flex items-start gap-2.5">
              <span class="text-quiz-ink-muted mt-0.5 shrink-0">
                <QuizIcon name={iconFor(entry) ?? ''} size={18} />
              </span>
              <span
                class="text-quiz-ink-secondary text-base/relaxed"
                set:html={renderInline(entry.sentence ?? '')}
              />
            </li>
          ))}
        </ul>
      </section>
    ) : null
  }

  {/* The payoff. The one block with a heavier border, on purpose. */}
  {
    moveBody !== 'none' ? (
      <section class="border-quiz-accent-edge bg-quiz-accent-tint mb-8 rounded-xl border-2 p-4 md:p-5">
        {mm?.moveHeading ? (
          <h2 class="text-quiz-accent-strong mb-3 flex items-center gap-2 text-lg font-bold">
            <QuizIcon name="next" size={18} />
            {mm.moveHeading}
          </h2>
        ) : null}
        {moveBody === 'move' ? (
          <>
            {result.reclaim?.sentence ? (
              <p
                class="text-quiz-ink mb-3 text-base/relaxed last:mb-0"
                set:html={renderInline(result.reclaim.sentence)}
              />
            ) : null}
            {result.redirect?.sentence ? (
              <p
                class="text-quiz-ink mb-3 text-base/relaxed last:mb-0"
                set:html={renderInline(result.redirect.sentence)}
              />
            ) : null}
          </>
        ) : (
          paragraphs(
            moveBody === 'wellPositioned' ? mm?.wellPositioned : mm?.noMove
          ).map((p) => (
            <p
              class="text-quiz-ink mb-3 text-base/relaxed last:mb-0"
              set:html={renderInline(p)}
            />
          ))
        )}
      </section>
    ) : null
  }

  {
    paragraphs(mm?.close).length > 0 ? (
      <section class="mb-8">
        {paragraphs(mm?.close).map((p) => (
          <p
            class="text-quiz-ink-secondary mb-3 text-base/relaxed last:mb-0"
            set:html={renderInline(p)}
          />
        ))}
      </section>
    ) : null
  }

  {
    mm?.cta ? (
      <section class="border-quiz-hairline border-t-[0.5px] pt-5">
        <div class="flex flex-wrap items-center justify-between gap-3">
          {mm.cta.body ? (
            <p class="text-quiz-ink-secondary text-base">{mm.cta.body}</p>
          ) : null}
          <a
            href={mm.cta.buttonHref}
            class="text-quiz-accent-strong inline-flex items-center gap-1.5 text-base font-medium hover:underline"
          >
            {mm.cta.buttonLabel}
            <QuizIcon name="next" size={16} />
          </a>
        </div>
      </section>
    ) : null
  }
</div>

---
/**
 * The map-move lead visual: a fixed grid of named kinds of work, each carrying a
 * bar showing how much of the taker's time went to it.
 *
 * It replaced a single two-segment balance bar. The bar could only say "this
 * much of your time was well spent"; this says which kinds of work the time went
 * to, which is what makes one area worth more attention than another.
 *
 * A true-proportion mosaic (boxes drawn at the size of their share) was built
 * first and rejected. It read beautifully on the common cases and then failed on
 * the one that matters: the box being recommended is by definition the one the
 * taker has given least time to, so it was always the smallest box on the
 * picture and always the first too small to hold its own label. The picture
 * argued against its own recommendation. Fixed boxes plus a bar say the same
 * thing about proportion while guaranteeing every box can be read.
 *
 * Three rules it has to keep:
 *
 * - **No number anywhere.** The bars carry the proportion. The result is a map
 *   of where the time went, not a grade.
 * - **No arrow.** The move is marked with two or three accent words on the two
 *   boxes involved (`tagFrom` / `tagTo`). A curve across the picture was hard to
 *   follow and made the whole thing busy.
 * - **Names name the work, never the person.** "the people work", not "the
 *   Coach". An archetype is the thing this quiz refuses to hand out.
 *
 * Built in HTML rather than SVG on purpose: an SVG's text scales with its
 * viewBox, so a 15px label renders at about 8px on a phone.
 */
import type { MapMoveShape, MapMoveShapeConfig } from '../types';

interface Props {
  config: MapMoveShapeConfig;
  shape: MapMoveShape;
  /** Box holding the reclaim target, tagged with `tagFrom`. */
  fromBoxId?: string;
  /** Box holding the redirect target, tagged with `tagTo`. */
  toBoxId?: string;
}

const { config, shape, fromBoxId, toBoxId } = Astro.props;

const shareOf = (id: string) =>
  shape.boxes.find((b) => b.boxId === id)?.share ?? 0;

const nameOf = (id: string) =>
  config.boxes.find((b) => b.id === id)?.name ?? id;

const rows = (['top', 'bottom'] as const)
  .map((row) => ({ row, boxes: config.boxes.filter((b) => b.row === row) }))
  .filter((r) => r.boxes.length > 0);

/**
 * Bars have to be comparable across boxes, and a row with one box makes that box
 * twice as wide as a box in a row of two. Left alone, a 24% share in the wide
 * box would draw the same length as a 48% share in a narrow one, which is
 * exactly backwards. Scaling each bar by its row's box count puts every bar on
 * one scale, so equal lengths mean equal shares wherever they sit.
 *
 * (The horizontal padding is the same in every box rather than scaled with it,
 * so a bar is off by at most ~12px on a 680px figure. Visible to a ruler, not to
 * a reader, and worth it to keep the boxes optically consistent.)
 */
const maxPerRow = Math.max(...rows.map((r) => r.boxes.length));
const barPercent = (id: string, boxesInRow: number) =>
  shareOf(id) * 100 * (boxesInRow / maxPerRow);

const TONE: Record<string, string> = {
  valuable: 'bg-quiz-valuable-tint text-quiz-valuable-strong',
  slipping: 'bg-quiz-slipping-tint text-quiz-slipping-strong',
  context: 'bg-quiz-context-panel text-quiz-ink-secondary',
};

const BAR: Record<string, string> = {
  valuable: 'bg-quiz-valuable-edge',
  slipping: 'bg-quiz-slipping-edge',
  context: 'bg-quiz-ink-muted',
};

// The one place a percentage is spoken: a screen reader gets nothing from bar
// lengths, so the shares have to be said out loud somewhere.
const ariaLabel = config.boxes
  .map((b) => `${b.name} ${Math.round(shareOf(b.id) * 100)}%`)
  .join(', ');

/**
 * The reading line. `mostlyTop` / `mostlyBottom` only print when they add
 * something: if the biggest box is already on the row where most of the time
 * went, naming that row restates the sentence before it ("Most of your Sprints
 * went to the mechanical work. Most of your time is in work the tools are
 * starting to do."). It earns its place when the two disagree, which is the
 * genuinely interesting case: one big box on one row, but the balance of
 * everything else on the other.
 */
const majorityRow = shape.topShare >= 0.5 ? 'top' : 'bottom';
const largestRow = config.boxes.find((b) => b.id === shape.largestBoxId)?.row;
const readingLines = [
  config.mostLine?.replace('{box}', nameOf(shape.largestBoxId)),
  largestRow !== majorityRow
    ? majorityRow === 'top'
      ? config.mostlyTop
      : config.mostlyBottom
    : undefined,
].filter(Boolean) as string[];
---

<figure class="mb-8">
  {
    config.label ? (
      <figcaption class="text-quiz-ink-secondary mb-3 text-sm">
        {config.label}
      </figcaption>
    ) : null
  }

  <p class="text-quiz-valuable-strong mb-2 text-center text-xs">
    {config.axisTop}
  </p>

  <div
    class="flex h-72 flex-col gap-1.5 md:h-80"
    role="img"
    aria-label={ariaLabel}
  >
    {
      rows.map((r) => (
        <div class="flex flex-1 gap-1.5">
          {r.boxes.map((b) => (
            <div
              class={`${TONE[b.tone]} flex flex-1 flex-col justify-between rounded-xl px-3 py-2.5 md:px-4 md:py-3`}
            >
              <div class="flex items-start justify-between gap-2">
                <span
                  class={`text-sm font-medium wrap-break-word md:text-base ${shareOf(b.id) > 0 ? '' : 'opacity-55'}`}
                >
                  {b.name}
                </span>
                {b.id === fromBoxId && config.tagFrom ? (
                  <span class="text-quiz-accent-strong shrink-0 text-xs font-medium">
                    {config.tagFrom}
                  </span>
                ) : b.id === toBoxId && config.tagTo ? (
                  <span class="text-quiz-accent-strong shrink-0 text-xs font-medium">
                    {config.tagTo}
                  </span>
                ) : null}
              </div>
              {/* No track behind the bar: an empty box simply has no bar. */}
              {shareOf(b.id) > 0 ? (
                <div
                  class={`${BAR[b.tone]} h-1.5 rounded-full`}
                  style={`width:${barPercent(b.id, r.boxes.length)}%`}
                />
              ) : null}
            </div>
          ))}
        </div>
      ))
    }
  </div>

  {
    config.axisNear || config.axisFar ? (
      <div class="text-quiz-ink-muted mt-2 flex justify-between text-xs">
        <span>{config.axisNear}</span>
        <span>{config.axisFar}</span>
      </div>
    ) : null
  }

  <p class="text-quiz-slipping-strong mt-1 text-center text-xs">
    {config.axisBottom}
  </p>

  {
    readingLines.length > 0 ? (
      <p class="text-quiz-ink-secondary mt-4 text-base/relaxed">
        {readingLines.join(' ')}
      </p>
    ) : null
  }
</figure>

