1	import { isScored } from './types';
2	import type {
3	  MapMoveEntry,
4	  MapMoveResult,
5	  MapMoveShape,
6	  QuizData,
7	  QuizResponses,
8	} from './types';
9	
10	/**
11	 * Pure logic for the `map-move` result style. Given the taker's responses, it
12	 * classifies each answer into gaining / slipping / context buckets, then picks
13	 * the single reclaim + redirect move from the quiz's priority ordering. All
14	 * copy lives in the quiz frontmatter; this module only decides which answers
15	 * and which move to surface.
16	 */
17	export function computeMapMove(
18	  quiz: QuizData,
19	  responses: QuizResponses
20	): MapMoveResult {
21	  const gaining: MapMoveEntry[] = [];
22	  const slipping: MapMoveEntry[] = [];
23	  const context: MapMoveEntry[] = [];
24	  // Keyed by question id so the move selection can look answers up by priority.
25	  const byQuestion = new Map<string, MapMoveEntry>();
26	
27	  for (const question of quiz.questions) {
28	    const optionIndex = responses[question.id];
29	    if (optionIndex === undefined) continue;
30	    // Profile answers say who the taker is, not how their sprints went. Keeping
31	    // them out here is what stops "I'm a project manager" turning up as a line
32	    // in the context strip and skewing the balance bar. They stay in the results
33	    // query (see buildMapMoveQuery) so the page could branch on them later.
34	    if (!isScored(question)) continue;
35	    const option = question.options[optionIndex];
36	    if (!option) continue;
37	
38	    const entry: MapMoveEntry = {
39	      questionId: question.id,
40	      optionIndex,
41	      bucket: option.bucket ?? 'mixed',
42	      sentence: option.mapSentence,
43	    };
44	    byQuestion.set(question.id, entry);
45	
46	    if (entry.bucket === 'gaining') gaining.push(entry);
47	    else if (entry.bucket === 'slipping') slipping.push(entry);
48	    else if (entry.bucket === 'context') context.push(entry);
49	    // 'mixed' answers do not appear in the map.
50	  }
51	
52	  const config = quiz.mapMove;
53	  const reclaimPriority = config?.reclaimPriority ?? [];
54	  const redirectPriority = config?.redirectPriority ?? [];
55	
56	  /**
57	   * An answer can win a half of the move only if it has something to say for
58	   * that half. The sentence is the opt-in, for both buckets.
59	   *
60	   * A `context` answer is never a gap, so it stays out of the map's problem
61	   * column and out of the shape's slipping side. But some constraints are real
62	   * problems the taker cannot ignore (no Product Owner to reach, impediments
63	   * that never surface, admin that doesn't shrink just because the role is
64	   * part-time), and leaving those in the soft context strip understates them:
65	   * "not your fault" is not the same as "not important". Writing the sentence
66	   * says the author has decided this constraint is actionable, and it promotes
67	   * the answer into the most prominent block on the page without blaming anyone.
68	   *
69	   * Requiring the sentence for `slipping` answers too is what stops the walk
70	   * dying on a high-priority answer that has no copy for this half. Before that,
71	   * `q2`'s "status and logistics desk" (first in `redirectPriority`, with a
72	   * `reclaimSentence` but no `redirectSentence`) won the redirect on 16% of
73	   * answer sets and then rendered nothing, so the taker was told what to stop
74	   * doing and never told where the time should go.
75	   */
76	  const eligible = (
77	    entry: MapMoveEntry,
78	    field: 'reclaimSentence' | 'redirectSentence'
79	  ): boolean =>
80	    (entry.bucket === 'slipping' || entry.bucket === 'context') &&
81	    !!optionSentence(quiz, entry, field);
82	
83	  const firstEligible = (
84	    priority: string[],
85	    field: 'reclaimSentence' | 'redirectSentence',
86	    excludeQuestionId?: string
87	  ): MapMoveEntry | null => {
88	    for (const questionId of priority) {
89	      const entry = byQuestion.get(questionId);
90	      if (
91	        entry &&
92	        eligible(entry, field) &&
93	        entry.questionId !== excludeQuestionId
94	      ) {
95	        return entry;
96	      }
97	    }
98	    return null;
99	  };
100	
101	  const reclaimEntry = firstEligible(reclaimPriority, 'reclaimSentence');
102	  // Never redirect into the same answer we're reclaiming from.
103	  const redirectEntry = firstEligible(
104	    redirectPriority,
105	    'redirectSentence',
106	    reclaimEntry?.questionId
107	  );
108	
109	  const reclaim = reclaimEntry
110	    ? {
111	        entry: reclaimEntry,
112	        sentence: optionSentence(quiz, reclaimEntry, 'reclaimSentence'),
113	        boxId: optionBox(quiz, reclaimEntry),
114	      }
115	    : null;
116	  const redirect = redirectEntry
117	    ? {
118	        entry: redirectEntry,
119	        sentence: optionSentence(quiz, redirectEntry, 'redirectSentence'),
120	        boxId: optionBox(quiz, redirectEntry),
121	      }
122	    : null;
123	
124	  const namedInMove = new Set(
125	    [reclaim?.entry.questionId, redirect?.entry.questionId].filter(Boolean)
126	  );
127	  const otherSlipping = slipping.filter((e) => !namedInMove.has(e.questionId));
128	
129	  return {
130	    gaining,
131	    slipping,
132	    context,
133	    reclaim,
134	    redirect,
135	    otherSlipping,
136	    // "little or nothing slipping" — the rare, well-positioned case. A context
137	    // answer that won either half of the move disqualifies it: there is a real
138	    // problem to name, and the results page renders this fallback *instead* of
139	    // the move, so leaving it true here would swallow the very thing we
140	    // surfaced. With no slipping answers, a non-null entry can only be a
141	    // context one, so these two checks bite in exactly that case.
142	    wellPositioned:
143	      slipping.length === 0 &&
144	      gaining.length > 0 &&
145	      reclaimEntry === null &&
146	      redirectEntry === null,
147	    framing: computeFraming(gaining.length, slipping.length, config?.framing),
148	    shape: computeShape(quiz, responses),
149	  };
150	}
