152	/**
153	 * The lead visual's proportions: how much of the taker's attention landed in
154	 * each declared box.
155	 *
156	 * Every answered option contributes, whatever its bucket, because this asks
157	 * "where did the time go" rather than "what went well". That is the opposite of
158	 * the map columns beside it, and deliberately so: a `context` answer is real
159	 * time spent and belongs in the shape, even though it is never counted as a gap.
160	 */
161	function computeShape(
162	  quiz: QuizData,
163	  responses: QuizResponses
164	): MapMoveShape | null {
165	  const boxes = quiz.mapMove?.shape?.boxes;
166	  if (!boxes?.length) return null;
167	
168	  const weights = new Map<string, number>(boxes.map((b) => [b.id, 0]));
169	  let total = 0;
170	  for (const question of quiz.questions) {
171	    if (!isScored(question)) continue;
172	    const option = question.options[responses[question.id] ?? -1];
173	    // An option needs both to say anything: which kind of work, and how much.
174	    if (!option?.box || !option.weight) continue;
175	    const current = weights.get(option.box);
176	    if (current === undefined) continue; // box id not declared; ignore it
177	    weights.set(option.box, current + option.weight);
178	    total += option.weight;
179	  }
180	  if (total === 0) return null;
181	
182	  const shares = boxes.map((b) => ({
183	    boxId: b.id,
184	    share: (weights.get(b.id) ?? 0) / total,
185	  }));
186	  const largest = shares.reduce((a, b) => (b.share > a.share ? b : a));
187	  const topShare = boxes
188	    .filter((b) => b.row === 'top')
189	    .reduce((sum, b) => sum + (weights.get(b.id) ?? 0) / total, 0);
190	
191	  return { boxes: shares, largestBoxId: largest.boxId, topShare };
192	}
