import { isScored } from './types';
import type {
  MapMoveEntry,
  MapMoveResult,
  MapMoveShape,
  QuizData,
  QuizResponses,
} from './types';

/**
 * Pure logic for the `map-move` result style. Given the taker's responses, it
 * classifies each answer into gaining / slipping / context buckets, then picks
 * the single reclaim + redirect move from the quiz's priority ordering. All
 * copy lives in the quiz frontmatter; this module only decides which answers
 * and which move to surface.
 */
export function computeMapMove(
  quiz: QuizData,
  responses: QuizResponses
): MapMoveResult {
  const gaining: MapMoveEntry[] = [];
  const slipping: MapMoveEntry[] = [];
  const context: MapMoveEntry[] = [];
  // Keyed by question id so the move selection can look answers up by priority.
  const byQuestion = new Map<string, MapMoveEntry>();

  for (const question of quiz.questions) {
    const optionIndex = responses[question.id];
    if (optionIndex === undefined) continue;
    // Profile answers say who the taker is, not how their sprints went. Keeping
    // them out here is what stops "I'm a project manager" turning up as a line
    // in the context strip and skewing the balance bar. They stay in the results
    // query (see buildMapMoveQuery) so the page could branch on them later.
    if (!isScored(question)) continue;
    const option = question.options[optionIndex];
    if (!option) continue;

    const entry: MapMoveEntry = {
      questionId: question.id,
      optionIndex,
      bucket: option.bucket ?? 'mixed',
      sentence: option.mapSentence,
    };
    byQuestion.set(question.id, entry);

    if (entry.bucket === 'gaining') gaining.push(entry);
    else if (entry.bucket === 'slipping') slipping.push(entry);
    else if (entry.bucket === 'context') context.push(entry);
    // 'mixed' answers do not appear in the map.
  }

  const config = quiz.mapMove;
  const reclaimPriority = config?.reclaimPriority ?? [];
  const redirectPriority = config?.redirectPriority ?? [];

  /**
   * An answer can win a half of the move only if it has something to say for
   * that half. The sentence is the opt-in, for both buckets.
   *
   * A `context` answer is never a gap, so it stays out of the map's problem
   * column and out of the shape's slipping side. But some constraints are real
   * problems the taker cannot ignore (no Product Owner to reach, impediments
   * that never surface, admin that doesn't shrink just because the role is
   * part-time), and leaving those in the soft context strip understates them:
   * "not your fault" is not the same as "not important". Writing the sentence
   * says the author has decided this constraint is actionable, and it promotes
   * the answer into the most prominent block on the page without blaming anyone.
   *
   * Requiring the sentence for `slipping` answers too is what stops the walk
   * dying on a high-priority answer that has no copy for this half. Before that,
   * `q2`'s "status and logistics desk" (first in `redirectPriority`, with a
   * `reclaimSentence` but no `redirectSentence`) won the redirect on 16% of
   * answer sets and then rendered nothing, so the taker was told what to stop
   * doing and never told where the time should go.
   */
  const eligible = (
    entry: MapMoveEntry,
    field: 'reclaimSentence' | 'redirectSentence'
  ): boolean =>
    (entry.bucket === 'slipping' || entry.bucket === 'context') &&
    !!optionSentence(quiz, entry, field);

  const firstEligible = (
    priority: string[],
    field: 'reclaimSentence' | 'redirectSentence',
    excludeQuestionId?: string
  ): MapMoveEntry | null => {
    for (const questionId of priority) {
      const entry = byQuestion.get(questionId);
      if (
        entry &&
        eligible(entry, field) &&
        entry.questionId !== excludeQuestionId
      ) {
        return entry;
      }
    }
    return null;
  };

  const reclaimEntry = firstEligible(reclaimPriority, 'reclaimSentence');
  // Never redirect into the same answer we're reclaiming from.
  const redirectEntry = firstEligible(
    redirectPriority,
    'redirectSentence',
    reclaimEntry?.questionId
  );

  const reclaim = reclaimEntry
    ? {
        entry: reclaimEntry,
        sentence: optionSentence(quiz, reclaimEntry, 'reclaimSentence'),
        boxId: optionBox(quiz, reclaimEntry),
      }
    : null;
  const redirect = redirectEntry
    ? {
        entry: redirectEntry,
        sentence: optionSentence(quiz, redirectEntry, 'redirectSentence'),
        boxId: optionBox(quiz, redirectEntry),
      }
    : null;

  const namedInMove = new Set(
    [reclaim?.entry.questionId, redirect?.entry.questionId].filter(Boolean)
  );
  const otherSlipping = slipping.filter((e) => !namedInMove.has(e.questionId));

  return {
    gaining,
    slipping,
    context,
    reclaim,
    redirect,
    otherSlipping,
    // "little or nothing slipping" — the rare, well-positioned case. A context
    // answer that won either half of the move disqualifies it: there is a real
    // problem to name, and the results page renders this fallback *instead* of
    // the move, so leaving it true here would swallow the very thing we
    // surfaced. With no slipping answers, a non-null entry can only be a
    // context one, so these two checks bite in exactly that case.
    wellPositioned:
      slipping.length === 0 &&
      gaining.length > 0 &&
      reclaimEntry === null &&
      redirectEntry === null,
    framing: computeFraming(gaining.length, slipping.length, config?.framing),
    shape: computeShape(quiz, responses),
  };
}

/**
 * The lead visual's proportions: how much of the taker's attention landed in
 * each declared box.
 *
 * Every answered option contributes, whatever its bucket, because this asks
 * "where did the time go" rather than "what went well". That is the opposite of
 * the map columns beside it, and deliberately so: a `context` answer is real
 * time spent and belongs in the shape, even though it is never counted as a gap.
 */
function computeShape(
  quiz: QuizData,
  responses: QuizResponses
): MapMoveShape | null {
  const boxes = quiz.mapMove?.shape?.boxes;
  if (!boxes?.length) return null;

  const weights = new Map<string, number>(boxes.map((b) => [b.id, 0]));
  let total = 0;
  for (const question of quiz.questions) {
    if (!isScored(question)) continue;
    const option = question.options[responses[question.id] ?? -1];
    // An option needs both to say anything: which kind of work, and how much.
    if (!option?.box || !option.weight) continue;
    const current = weights.get(option.box);
    if (current === undefined) continue; // box id not declared; ignore it
    weights.set(option.box, current + option.weight);
    total += option.weight;
  }
  if (total === 0) return null;

  const shares = boxes.map((b) => ({
    boxId: b.id,
    share: (weights.get(b.id) ?? 0) / total,
  }));
  const largest = shares.reduce((a, b) => (b.share > a.share ? b : a));
  const topShare = boxes
    .filter((b) => b.row === 'top')
    .reduce((sum, b) => sum + (weights.get(b.id) ?? 0) / total, 0);

  return { boxes: shares, largestBoxId: largest.boxId, topShare };
}

/** The shape box an answered option belongs to, if it declares one. */
function optionBox(quiz: QuizData, entry: MapMoveEntry): string | undefined {
  const question = quiz.questions.find((q) => q.id === entry.questionId);
  return question?.options[entry.optionIndex]?.box;
}

function optionSentence(
  quiz: QuizData,
  entry: MapMoveEntry,
  key: 'reclaimSentence' | 'redirectSentence'
): string | undefined {
  const question = quiz.questions.find((q) => q.id === entry.questionId);
  return question?.options[entry.optionIndex]?.[key];
}

/**
 * A light, descriptive framing bucket based on the balance of gaining vs
 * slipping answers (context and mixed answers are ignored so a part-timer's
 * constraints never drag the framing toward "slipping"). Returns null when the
 * quiz supplies no framing copy.
 */
function computeFraming(
  gainingCount: number,
  slippingCount: number,
  framing?: { gaining: string; mixed: string; slipping: string }
): 'gaining' | 'mixed' | 'slipping' | null {
  if (!framing) return null;
  const decisive = gainingCount + slippingCount;
  if (decisive === 0) return 'mixed';
  const ratio = gainingCount / decisive;
  if (ratio >= 0.66) return 'gaining';
  if (ratio <= 0.34) return 'slipping';
  return 'mixed';
}

// The map-move results page is stateless: the taker's raw answers ride in the
// query string so the page can recompute the map on load. Encoded as a single
// `a` param, `qid-index` pairs joined by `.` (ids never contain those chars).
export function buildMapMoveQuery(
  quiz: QuizData,
  responses: QuizResponses
): URLSearchParams {
  const params = new URLSearchParams();
  const pairs: string[] = [];
  for (const question of quiz.questions) {
    const optionIndex = responses[question.id];
    if (optionIndex === undefined) continue;
    pairs.push(`${question.id}-${optionIndex}`);
  }
  params.set('a', pairs.join('.'));
  return params;
}

export function parseMapMoveResponses(params: URLSearchParams): QuizResponses {
  const responses: QuizResponses = {};
  const raw = params.get('a');
  if (!raw) return responses;
  for (const pair of raw.split('.')) {
    const sep = pair.lastIndexOf('-');
    if (sep <= 0) continue;
    const id = pair.slice(0, sep);
    const index = parseInt(pair.slice(sep + 1), 10);
    if (id && Number.isInteger(index) && index >= 0) responses[id] = index;
  }
  return responses;
}

