<Layout
  title={data.title}
  description={data.description ?? data.title}
  includeCoursesCTA={false}
  hideChrome={true}
>
  <div class="bg-quiz-page min-h-screen">
    <header class="border-quiz-hairline border-b-[0.5px]">
      <div class="mx-auto max-w-170 px-4 py-3">
        <a href="/" aria-label="Agile Pain Relief home">
          <img src={Logo.src} alt="Agile Pain Relief" class="h-9 w-auto" />
        </a>
      </div>
    </header>

    <div class="mx-auto max-w-170 px-4 py-10 md:py-14">
      <div data-quiz-chrome>
        <section class="mb-8">
          <h1
            class="text-quiz-ink max-w-[32ch] text-3xl/tight font-bold md:text-4xl/tight"
          >
            {data.heroHeading ?? data.title}
          </h1>
          {
            /* 60ch on every body paragraph of the cover, matching the measure
              inside `QuizIntroCard` at the foot of the page: a column that
              changes width partway down reads as two different pages. */
          }
          {
            data.heroBody ? (
              <p class="text-quiz-ink-secondary mt-4 max-w-[60ch] text-base/relaxed">
                {data.heroBody}
              </p>
            ) : null
          }
          {
            persuasionParagraphs.map((paragraph) => (
              <p class="text-quiz-ink-muted mt-3 max-w-[60ch] text-base/relaxed">
                {paragraph}
              </p>
            ))
          }
          {
            showHeroButton ? (
              <div class="mt-7">
                <button
                  type="button"
                  data-quiz-start
                  class="bg-quiz-ink focus:ring-quiz-accent-strong rounded-lg px-5 py-2.5 text-base font-medium text-white transition hover:opacity-90 focus:ring-2 focus:ring-offset-2 focus:outline-none"
                >
                  {heroButtonLabel}
                </button>
                {/* Set in italic body size rather than muted small print: this
                  is the one thing we ask of the taker, and a quiz that sells
                  itself on candour cannot whisper the ask. Held to the same
                  measure as the hero body so it reads as part of the pitch. */}
                {heroButtonNote ? (
                  <p class="text-quiz-ink-secondary mt-3 max-w-[60ch] text-base italic">
                    {heroButtonNote}
                  </p>
                ) : null}
              </div>
            ) : null
          }
        </section>

