import { isScored } from './types';
import type {
  MapMoveEntry,
  MapMoveResult,
  MapMoveShape,
  QuizData,
  QuizResponses,
} from './types';

/**
 * Pure logic for the `map-move` result style. Given the taker's responses, it
 * classifies each answer into gaining / slipping / context buckets, then picks
 * the single reclaim + redirect move from the quiz's priority ordering. All
 * copy lives in the quiz frontmatter; this module only decides which answers
 * and which move to surface.
 */
export function computeMapMove(
  quiz: QuizData,
  responses: QuizResponses
): MapMoveResult {
  const gaining: MapMoveEntry[] = [];
  const slipping: MapMoveEntry[] = [];
  const context: MapMoveEntry[] = [];
  // Keyed by question id so the move selection can look answers up by priority.
  const byQuestion = new Map<string, MapMoveEntry>();

  for (const question of quiz.questions) {
    const optionIndex = responses[question.id];
    if (optionIndex === undefined) continue;
    // Profile answers say who the taker is, not how their sprints went. Keeping
    // them out here is what stops "I'm a project manager" turning up as a line
    // in the context strip and skewing the balance bar. They stay in the results
    // query (see buildMapMoveQuery) so the page could branch on them later.
    if (!isScored(question)) continue;
    const option = question.options[optionIndex];
    if (!option) continue;

    const entry: MapMoveEntry = {
      questionId: question.id,
      optionIndex,
      bucket: option.bucket ?? 'mixed',
      sentence: option.mapSentence,
    };
    byQuestion.set(question.id, entry);

    if (entry.bucket === 'gaining') gaining.push(entry);
    else if (entry.bucket === 'slipping') slipping.push(entry);
    else if (entry.bucket === 'context') context.push(entry);
    // 'mixed' answers do not appear in the map.
  }

  const config = quiz.mapMove;
  const reclaimPriority = config?.reclaimPriority ?? [];
  const redirectPriority = config?.redirectPriority ?? [];

  /**
   * An answer can win a half of the move only if it has something to say for
   * that half. The sentence is the opt-in, for both buckets.
   *
   * A `context` answer is never a gap, so it stays out of the map's problem
   * column and out of the shape's slipping side. But some constraints are real
   * problems the taker cannot ignore (no Product Owner to reach, impediments
   * that never surface, admin that doesn't shrink just because the role is
   * part-time), and leaving those in the soft context strip understates them:
   * "not your fault" is not the same as "not important". Writing the sentence
   * says the author has decided this constraint is actionable, and it promotes
   * the answer into the most prominent block on the page without blaming anyone.
   *
   * Requiring the sentence for `slipping` answers too is what stops the walk
   * dying on a high-priority answer that has no copy for this half. Before that,
   * `q2`'s "status and logistics desk" (first in `redirectPriority`, with a
   * `reclaimSentence` but no `redirectSentence`) won the redirect on 16% of
   * answer sets and then rendered nothing, so the taker was told what to stop
   * doing and never told where the time should go.
   */
  const eligible = (
    entry: MapMoveEntry,
    field: 'reclaimSentence' | 'redirectSentence'
  ): boolean =>
    (entry.bucket === 'slipping' || entry.bucket === 'context') &&
    !!optionSentence(quiz, entry, field);

  const firstEligible = (
    priority: string[],
    field: 'reclaimSentence' | 'redirectSentence',
    excludeQuestionId?: string
  ): MapMoveEntry | null => {
    for (const questionId of priority) {
      const entry = byQuestion.get(questionId);
      if (
        entry &&
        eligible(entry, field) &&
        entry.questionId !== excludeQuestionId
      ) {
        return entry;
      }
    }
    return null;
  };

  const reclaimEntry = firstEligible(reclaimPriority, 'reclaimSentence');
  // Never redirect into the same answer we're reclaiming from.
  const redirectEntry = firstEligible(
    redirectPriority,
    'redirectSentence',
    reclaimEntry?.questionId
  );

  const reclaim = reclaimEntry
    ? {
        entry: reclaimEntry,
        sentence: optionSentence(quiz, reclaimEntry, 'reclaimSentence'),
        boxId: optionBox(quiz, reclaimEntry),
      }
    : null;
  const redirect = redirectEntry
    ? {
        entry: redirectEntry,
        sentence: optionSentence(quiz, redirectEntry, 'redirectSentence'),
        boxId: optionBox(quiz, redirectEntry),
      }
    : null;

  const namedInMove = new Set(
    [reclaim?.entry.questionId, redirect?.entry.questionId].filter(Boolean)
  );
  const otherSlipping = slipping.filter((e) => !namedInMove.has(e.questionId));

  return {
    gaining,
    slipping,
    context,
    reclaim,
    redirect,
    otherSlipping,
    // "little or nothing slipping" — the rare, well-positioned case. A context
    // answer that won either half of the move disqualifies it: there is a real
    // problem to name, and the results page renders this fallback *instead* of
    // the move, so leaving it true here would swallow the very thing we
    // surfaced. With no slipping answers, a non-null entry can only be a
    // context one, so these two checks bite in exactly that case.
    wellPositioned:
      slipping.length === 0 &&
      gaining.length > 0 &&
      reclaimEntry === null &&
      redirectEntry === null,
    framing: computeFraming(gaining.length, slipping.length, config?.framing),
    shape: computeShape(quiz, responses),
  };
}

/**
 * The lead visual's proportions: how much of the taker's attention landed in
 * each declared box.
 *
 * Every answered option contributes, whatever its bucket, because this asks
 * "where did the time go" rather than "what went well". That is the opposite of
 * the map columns beside it, and deliberately so: a `context` answer is real
 * time spent and belongs in the shape, even though it is never counted as a gap.
 */
function computeShape(
  quiz: QuizData,
  responses: QuizResponses
): MapMoveShape | null {
  const boxes = quiz.mapMove?.shape?.boxes;
  if (!boxes?.length) return null;

  const weights = new Map<string, number>(boxes.map((b) => [b.id, 0]));
  let total = 0;
  for (const question of quiz.questions) {
    if (!isScored(question)) continue;
    const option = question.options[responses[question.id] ?? -1];
    // An option needs both to say anything: which kind of work, and how much.
    if (!option?.box || !option.weight) continue;
    const current = weights.get(option.box);
    if (current === undefined) continue; // box id not declared; ignore it
    weights.set(option.box, current + option.weight);
    total += option.weight;
  }
  if (total === 0) return null;

  const shares = boxes.map((b) => ({
    boxId: b.id,
    share: (weights.get(b.id) ?? 0) / total,
  }));
  const largest = shares.reduce((a, b) => (b.share > a.share ? b : a));
  const topShare = boxes
    .filter((b) => b.row === 'top')
    .reduce((sum, b) => sum + (weights.get(b.id) ?? 0) / total, 0);

  return { boxes: shares, largestBoxId: largest.boxId, topShare };
}

/** The shape box an answered option belongs to, if it declares one. */
function optionBox(quiz: QuizData, entry: MapMoveEntry): string | undefined {
  const question = quiz.questions.find((q) => q.id === entry.questionId);
  return question?.options[entry.optionIndex]?.box;
}

function optionSentence(
  quiz: QuizData,
  entry: MapMoveEntry,
  key: 'reclaimSentence' | 'redirectSentence'
): string | undefined {
  const question = quiz.questions.find((q) => q.id === entry.questionId);
  return question?.options[entry.optionIndex]?.[key];
}

/**
 * A light, descriptive framing bucket based on the balance of gaining vs
 * slipping answers (context and mixed answers are ignored so a part-timer's
 * constraints never drag the framing toward "slipping"). Returns null when the
 * quiz supplies no framing copy.
 */
function computeFraming(
  gainingCount: number,
  slippingCount: number,
  framing?: { gaining: string; mixed: string; slipping: string }
): 'gaining' | 'mixed' | 'slipping' | null {
  if (!framing) return null;
  const decisive = gainingCount + slippingCount;
  if (decisive === 0) return 'mixed';
  const ratio = gainingCount / decisive;
  if (ratio >= 0.66) return 'gaining';
  if (ratio <= 0.34) return 'slipping';
  return 'mixed';
}

// The map-move results page is stateless: the taker's raw answers ride in the
// query string so the page can recompute the map on load. Encoded as a single
// `a` param, `qid-index` pairs joined by `.` (ids never contain those chars).
export function buildMapMoveQuery(
  quiz: QuizData,
  responses: QuizResponses
): URLSearchParams {
  const params = new URLSearchParams();
  const pairs: string[] = [];
  for (const question of quiz.questions) {
    const optionIndex = responses[question.id];
    if (optionIndex === undefined) continue;
    pairs.push(`${question.id}-${optionIndex}`);
  }
  params.set('a', pairs.join('.'));
  return params;
}

export function parseMapMoveResponses(params: URLSearchParams): QuizResponses {
  const responses: QuizResponses = {};
  const raw = params.get('a');
  if (!raw) return responses;
  for (const pair of raw.split('.')) {
    const sep = pair.lastIndexOf('-');
    if (sep <= 0) continue;
    const id = pair.slice(0, sep);
    const index = parseInt(pair.slice(sep + 1), 10);
    if (id && Number.isInteger(index) && index >= 0) responses[id] = index;
  }
  return responses;
}

---
/**
 * Renders the `map-move` result style: a per-answer map (work getting more
 * valuable vs. work a tool can take) plus one recommended move. Everything the
 * component prints comes from the quiz's `mapMove` frontmatter and the chosen
 * options' sentences, so the engine stays free of any site-specific wording.
 *
 * The design is a map, not a grade. There is no number, letter or tier title
 * anywhere on the page: the lead visual is `MapMoveShape`, whose boxes are
 * sized by the proportion of time that went to each kind of work, and colour is
 * always backed by an icon, a label and a position so it survives greyscale and
 * colour-blindness. Surfaces are flat with hairline borders; the one move is
 * the single block allowed a heavier border, because it is the payoff.
 *
 * The page passes the taker's decoded responses; scoring/selection happens in
 * `computeMapMove`. This component is presentation only.
 */
import { computeMapMove } from '../map-move';
import type { MapMoveEntry, QuizData, QuizResponses } from '../types';
import MapMoveShape from './MapMoveShape.astro';
import QuizIcon from './QuizIcon';

interface Props {
  quiz: QuizData;
  responses: QuizResponses;
}

const { quiz, responses } = Astro.props;
const mm = quiz.mapMove;
const result = computeMapMove(quiz, responses);

// Minimal, escaped inline markdown: `[label](url)` links only. Content is
// author-controlled (frontmatter), but escaping first keeps this safe if that
// ever changes.
function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function renderInline(text: string): string {
  return escapeHtml(text).replace(
    /\[([^\]]+)\]\(([^)\s]+)\)/g,
    (_m, label: string, url: string) => {
      const external = /^https?:\/\//i.test(url);
      const attrs = external
        ? ` target="_blank" rel="noopener noreferrer"`
        : '';
      return `<a href="${url}"${attrs} class="text-quiz-accent-strong underline">${label}</a>`;
    }
  );
}

function paragraphs(text?: string): string[] {
  if (!text) return [];
  return text
    .split(/\n\s*\n/)
    .map((p) => p.trim())
    .filter(Boolean);
}

// Each answer's icon comes from the option the taker chose, so the map reads as
// concepts rather than bullets.
function iconFor(entry: MapMoveEntry): string | undefined {
  const question = quiz.questions.find((q) => q.id === entry.questionId);
  return question?.options[entry.optionIndex]?.icon;
}

const largestBoxId = result.shape?.largestBoxId;
const largestBoxName = largestBoxId
  ? (mm?.shape?.boxes.find((b) => b.id === largestBoxId)?.name ?? largestBoxId)
  : undefined;

const heading =
  mm?.heading?.includes('{box}') && !largestBoxName
    ? (mm.headingFallback ?? quiz.title)
    : (mm?.heading?.replace('{box}', largestBoxName ?? '') ?? quiz.title);

// A context answer with no `mapSentence` has nothing to say. Filtering here
// rather than in the loop also keeps the panel itself from rendering as a bare
// heading over an empty list.
const contextWithSentences = result.context.filter((entry) => entry.sentence);

/**
 * What the payoff block should say. `'none'` drops the block entirely rather
 * than printing an accent-bordered box containing only its heading, which is
 * what a taker who answered in the middle of every question used to get: no
 * move to make, but not well positioned either, so neither branch had copy.
 */
const moveBody: 'wellPositioned' | 'move' | 'noMove' | 'none' =
  result.wellPositioned && mm?.wellPositioned
    ? 'wellPositioned'
    : result.reclaim?.sentence || result.redirect?.sentence
      ? 'move'
      : mm?.noMove
        ? 'noMove'
        : 'none';
---

<div class="mx-auto max-w-170">
  <header class="mb-8">
    {
      mm?.eyebrow ? (
        <p class="text-quiz-accent-strong mb-2 text-sm">{mm.eyebrow}</p>
      ) : null
    }
    <h1 class="text-quiz-ink text-2xl/tight font-bold md:text-3xl/tight">
      {heading}
    </h1>
    {
      paragraphs(mm?.opening).map((p) => (
        <p
          class="text-quiz-ink-secondary mt-4 text-base/relaxed"
          set:html={renderInline(p)}
        />
      ))
    }
  </header>

  {/* The lead visual: proportions, deliberately without a number on them. */}
  {
    mm?.shape && result.shape ? (
      <MapMoveShape
        config={mm.shape}
        shape={result.shape}
        fromBoxId={result.reclaim?.sentence ? result.reclaim.boxId : undefined}
        toBoxId={result.redirect?.sentence ? result.redirect.boxId : undefined}
      />
    ) : null
  }

  {/* The map: two columns, what is gaining and what a tool can take. */}
  <section class="mb-8 grid grid-cols-1 gap-3.5 md:grid-cols-2">
    <div
      class="border-quiz-hairline bg-quiz-card rounded-xl border-[0.5px] p-4 md:px-5"
    >
      <h2
        class="text-quiz-valuable-strong mb-3 flex items-center gap-2 text-lg font-bold"
      >
        <QuizIcon name="gaining" size={18} />
        {mm?.gainingHeading}
      </h2>
      {
        result.gaining.length > 0 ? (
          <ul class="space-y-3">
            {result.gaining.map((entry) => (
              <li class="flex items-start gap-2.5">
                <span class="text-quiz-valuable-strong mt-0.5 shrink-0">
                  <QuizIcon name={iconFor(entry) ?? ''} size={18} />
                </span>
                <span
                  class="text-quiz-ink text-base/relaxed"
                  set:html={renderInline(entry.sentence ?? '')}
                />
              </li>
            ))}
          </ul>
        ) : mm?.gainingEmpty ? (
          <p class="text-quiz-ink-muted text-base/relaxed">{mm.gainingEmpty}</p>
        ) : null
      }
    </div>

    <div
      class="border-quiz-hairline bg-quiz-card rounded-xl border-[0.5px] p-4 md:px-5"
    >
      <h2
        class="text-quiz-slipping-strong mb-3 flex items-center gap-2 text-lg font-bold"
      >
        <QuizIcon name="slipping" size={18} />
        {mm?.slippingHeading}
      </h2>
      {
        result.slipping.length > 0 ? (
          <ul class="space-y-3">
            {result.slipping.map((entry) => (
              <li class="flex items-start gap-2.5">
                <span class="text-quiz-slipping-strong mt-0.5 shrink-0">
                  <QuizIcon name={iconFor(entry) ?? ''} size={18} />
                </span>
                <span
                  class="text-quiz-ink text-base/relaxed"
                  set:html={renderInline(entry.sentence ?? '')}
                />
              </li>
            ))}
          </ul>
        ) : mm?.slippingEmpty ? (
          <p class="text-quiz-ink-muted text-base/relaxed">
            {mm.slippingEmpty}
          </p>
        ) : null
      }
    </div>
  </section>

  {/* Context: the constraints. Visibly softer, and never counted as a gap. */}
  {
    contextWithSentences.length > 0 ? (
      <section class="bg-quiz-context-panel mb-8 rounded-xl p-4 md:p-5">
        {mm?.contextHeading ? (
          <p class="text-quiz-ink-secondary mb-3 text-sm">
            {mm.contextHeading}
          </p>
        ) : null}
        <ul class="space-y-3">
          {contextWithSentences.map((entry) => (
            <li class="flex items-start gap-2.5">
              <span class="text-quiz-ink-muted mt-0.5 shrink-0">
                <QuizIcon name={iconFor(entry) ?? ''} size={18} />
              </span>
              <span
                class="text-quiz-ink-secondary text-base/relaxed"
                set:html={renderInline(entry.sentence ?? '')}
              />
            </li>
          ))}
        </ul>
      </section>
    ) : null
  }

  {/* The payoff. The one block with a heavier border, on purpose. */}
  {
    moveBody !== 'none' ? (
      <section class="border-quiz-accent-edge bg-quiz-accent-tint mb-8 rounded-xl border-2 p-4 md:p-5">
        {mm?.moveHeading ? (
          <h2 class="text-quiz-accent-strong mb-3 flex items-center gap-2 text-lg font-bold">
            <QuizIcon name="next" size={18} />
            {mm.moveHeading}
          </h2>
        ) : null}
        {moveBody === 'move' ? (
          <>
            {result.reclaim?.sentence ? (
              <p
                class="text-quiz-ink mb-3 text-base/relaxed last:mb-0"
                set:html={renderInline(result.reclaim.sentence)}
              />
            ) : null}
            {result.redirect?.sentence ? (
              <p
                class="text-quiz-ink mb-3 text-base/relaxed last:mb-0"
                set:html={renderInline(result.redirect.sentence)}
              />
            ) : null}
          </>
        ) : (
          paragraphs(
            moveBody === 'wellPositioned' ? mm?.wellPositioned : mm?.noMove
          ).map((p) => (
            <p
              class="text-quiz-ink mb-3 text-base/relaxed last:mb-0"
              set:html={renderInline(p)}
            />
          ))
        )}
      </section>
    ) : null
  }

  {
    paragraphs(mm?.close).length > 0 ? (
      <section class="mb-8">
        {paragraphs(mm?.close).map((p) => (
          <p
            class="text-quiz-ink-secondary mb-3 text-base/relaxed last:mb-0"
            set:html={renderInline(p)}
          />
        ))}
      </section>
    ) : null
  }

  {
    mm?.cta ? (
      <section class="border-quiz-hairline border-t-[0.5px] pt-5">
        <div class="flex flex-wrap items-center justify-between gap-3">
          {mm.cta.body ? (
            <p class="text-quiz-ink-secondary text-base">{mm.cta.body}</p>
          ) : null}
          <a
            href={mm.cta.buttonHref}
            class="text-quiz-accent-strong inline-flex items-center gap-1.5 text-base font-medium hover:underline"
          >
            {mm.cta.buttonLabel}
            <QuizIcon name="next" size={16} />
          </a>
        </div>
      </section>
    ) : null
  }
</div>

---
/**
 * Renders the `map-move` result style: a per-answer map (work getting more
 * valuable vs. work a tool can take) plus one recommended move. Everything the
 * component prints comes from the quiz's `mapMove` frontmatter and the chosen
 * options' sentences, so the engine stays free of any site-specific wording.
 *
 * The design is a map, not a grade. There is no number, letter or tier title
 * anywhere on the page: the lead visual is `MapMoveShape`, whose boxes are
 * sized by the proportion of time that went to each kind of work, and colour is
 * always backed by an icon, a label and a position so it survives greyscale and
 * colour-blindness. Surfaces are flat with hairline borders; the one move is
 * the single block allowed a heavier border, because it is the payoff.
 *
 * The page passes the taker's decoded responses; scoring/selection happens in
 * `computeMapMove`. This component is presentation only.
 */
import { computeMapMove, resolveMapMoveCopy } from '../map-move';
import type { MapMoveEntry, QuizData, QuizResponses } from '../types';
import MapMoveShape from './MapMoveShape.astro';
import QuizIcon from './QuizIcon';

interface Props {
  quiz: QuizData;
  responses: QuizResponses;
}

const { quiz, responses } = Astro.props;
const mm = quiz.mapMove;
const result = computeMapMove(quiz, responses);

// Minimal, escaped inline markdown: `[label](url)` links only. Content is
// author-controlled (frontmatter), but escaping first keeps this safe if that
// ever changes.
function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function renderInline(text: string): string {
  return escapeHtml(text).replace(
    /\[([^\]]+)\]\(([^)\s]+)\)/g,
    (_m, label: string, url: string) => {
      const external = /^https?:\/\//i.test(url);
      const attrs = external
        ? ` target="_blank" rel="noopener noreferrer"`
        : '';
      return `<a href="${url}"${attrs} class="text-quiz-accent-strong underline">${label}</a>`;
    }
  );
}

function paragraphs(text?: string): string[] {
  if (!text) return [];
  return text
    .split(/\n\s*\n/)
    .map((p) => p.trim())
    .filter(Boolean);
}

// Each answer's icon comes from the option the taker chose, so the map reads as
// concepts rather than bullets.
function iconFor(entry: MapMoveEntry): string | undefined {
  const question = quiz.questions.find((q) => q.id === entry.questionId);
  return question?.options[entry.optionIndex]?.icon;
}

const largestBoxId = result.shape?.largestBoxId;
const largestBoxName = largestBoxId
  ? (mm?.shape?.boxes.find((b) => b.id === largestBoxId)?.name ?? largestBoxId)
  : undefined;

const heading =
  mm?.heading?.includes('{box}') && !largestBoxName
    ? (mm.headingFallback ?? quiz.title)
    : (mm?.heading?.replace('{box}', largestBoxName ?? '') ?? quiz.title);

// A context answer with no `mapSentence` has nothing to say. Filtering here
// rather than in the loop also keeps the panel itself from rendering as a bare
// heading over an empty list.
const contextWithSentences = result.context.filter((entry) => entry.sentence);

/**
 * What the payoff block should say. `'none'` drops the block entirely rather
 * than printing an accent-bordered box containing only its heading, which is
 * what a taker who answered in the middle of every question used to get: no
 * move to make, but not well positioned either, so neither branch had copy.
 */
const moveBody: 'wellPositioned' | 'move' | 'noMove' | 'none' =
  result.wellPositioned && mm?.wellPositioned
    ? 'wellPositioned'
    : result.reclaim?.sentence || result.redirect?.sentence
      ? 'move'
      : mm?.noMove
        ? 'noMove'
        : 'none';
